// Canonical syntax/privacy primitives for provider input. The browser copy is
// generated by scripts/build-source-input-policy.mjs and parity-tested.
// This is not a network/SSRF allowlist: server destination checks still apply.
export const SOURCE_ATTEMPT_PATH_SHAPES = Object.freeze([
  "root", "get.php", "player_api.php", ".m3u8", ".m3u", "web_page", "other", "invalid",
]);

const MULTI_LABEL_PUBLIC_SUFFIXES = new Set([
  "co.in", "firm.in", "gen.in", "ind.in", "net.in", "org.in",
  "com.bd", "net.bd", "org.bd", "com.pk", "net.pk", "org.pk",
  "co.th", "in.th", "or.th", "com.vn", "net.vn", "org.vn",
  "co.id", "web.id", "or.id", "com.my", "net.my", "org.my",
  "co.ma", "net.ma", "com.dz", "org.dz", "com.tn", "org.tn",
  "co.uk", "org.uk", "me.uk", "com.au", "net.au", "org.au",
  "co.ae", "com.sa",
]);

function isIpv4(hostname) {
  const parts = hostname.split(".");
  return parts.length === 4 && parts.every((part) => {
    if (!/^(?:0|[1-9]\d{0,2})$/.test(part)) return false;
    return Number(part) <= 255;
  });
}

export function normalizeSourceInputHostname(hostname) {
  return String(hostname ?? "").trim().toLowerCase().replace(/^\[|\]$/g, "").replace(/\.$/, "");
}

function isSourceAttemptHostname(hostname) {
  if (!hostname || hostname.length > 253) return false;
  if (isIpv4(hostname)) return true;
  if (hostname.includes(":")) {
    if (!/^[0-9a-f:.]+$/.test(hostname)) return false;
    try { return new URL(`http://[${hostname}]/`).hostname.startsWith("["); }
    catch { return false; }
  }
  const labels = hostname.split(".");
  return labels.length >= 2
    && labels.every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))
    && /[a-z]/.test(labels.at(-1));
}

export function parseSourceInputUrl(raw) {
  const value = String(raw ?? "").trim();
  if (!value || /[\s\u0000-\u001f\u007f\\]/u.test(value)) return null;
  try {
    const explicitScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(value);
    // Validate the ORIGINAL input before adding a scheme or extracting logins.
    if (!explicitScheme && value.split(/[/?#]/, 1)[0].includes("@")) return null;
    const candidate = explicitScheme ? value : `http://${value}`;
    const parsed = new URL(candidate);
    if (!["http:", "https:"].includes(parsed.protocol)) return null;
    const hostname = normalizeSourceInputHostname(parsed.hostname);
    if (!isSourceAttemptHostname(hostname)) return null;
    const authority = candidate.slice(candidate.indexOf("://") + 3).split(/[/?#]/, 1)[0];
    const hostPort = authority.slice(authority.lastIndexOf("@") + 1);
    const rawHost = hostPort.startsWith("[")
      ? hostPort.slice(0, hostPort.indexOf("]") + 1) : hostPort.split(":", 1)[0];
    // WHATWG rewrites numeric usernames and shorthand/octal IPv4. Reject them.
    if (isIpv4(hostname) && !isIpv4(rawHost.replace(/\.$/, ""))) return null;
    return parsed;
  } catch { return null; }
}

// Bounded reason codes only: never return raw input or credentials in feedback.
export function sourceInputProblem(raw) {
  const value = String(raw ?? "").trim();
  if (!value) return "empty";
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)
      && value.split(/[/?#]/, 1)[0].includes("@")) return "email_or_login";
  if (parseSourceInputUrl(value)) return null;
  const host = value.replace(/^https?:\/\//i, "").split(/[/?#]/, 1)[0];
  return /^[\p{L}\p{N}_-]+$/u.test(host) && !/^\d+$/.test(host) ? "name_not_url" : "invalid_address";
}

export function classifySourceAttemptPath(raw) {
  const parsed = parseSourceInputUrl(raw);
  if (!parsed) return "invalid";
  let pathname;
  try { pathname = decodeURIComponent(parsed.pathname || "/"); }
  catch { pathname = parsed.pathname || "/"; }
  pathname = pathname.toLowerCase().replace(/\/{2,}/g, "/");
  const parts = pathname.split("/").filter(Boolean);
  if (!parts.length) return "root";
  if (parts.includes("get.php")) return "get.php";
  if (parts.includes("player_api.php")) return "player_api.php";
  if (pathname.endsWith(".m3u8")) return ".m3u8";
  if (pathname.endsWith(".m3u")) return ".m3u";
  if (/\.(?:html?|xhtml)$/.test(pathname)) return "web_page";
  return "other";
}

export function normalizedSourceAttemptDomain(hostname) {
  const normalized = normalizeSourceInputHostname(hostname);
  if (!isSourceAttemptHostname(normalized)) return null;
  if (isIpv4(normalized) || normalized.includes(":")) return "ip-address";
  if (normalized.endsWith(".local")) return "local-address";
  const labels = normalized.split(".");
  if (labels.length <= 2) return normalized;
  return MULTI_LABEL_PUBLIC_SUFFIXES.has(labels.slice(-2).join("."))
    ? labels.slice(-3).join(".") : labels.slice(-2).join(".");
}
